if(e.range<6){ringFx(e.x+d.x*1.4,e.z+d.z*1.4,e.range*.6,e.team<0?0xfac57c:teamColors[e.team],.18);for(const t of enemies(e,e.range+1))if(((t.x-e.x)*d.x+(t.z-e.z)*d.z)/(dist(e,t)||1)>-.1)damage(t,e.damage,e);if(e.mods.blade)shoot(e,d,{damage:e.damage*.55,range:10,pierce:true,color:0x92ead2});}
