window.addEventListener('keydown',e=>{if([' ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))e.preventDefault();if(e.repeat)return;const k=e.key.toLowerCase();if(k==='escape'){if(state==='shop')resume();else pauseGame();return}if(state!=='playing')return;keys.add(k);if(k==='q')cast(player,0);if(k==='e')cast(player,1);if(k==='r')cast(player,2);if(k===' ')cast(player,3);if(k==='g')command();if(k==='b')showShop();});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();mouseDown=false;touchVector={x:0,z:0};if(state==='playing')pauseGame()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pauseGame()});$('pause').onclick=pauseGame;$('sound').onclick=()=>{muted=!muted;$('sound').textContent=muted?'♫ 靜音':'♫ 音效';if(!muted)audioCtx?.resume()};$('shopButton').onclick=showShop;$('minimap').onclick=e=>{const r=e.currentTarget.getBoundingClientRect();command((e.clientX-r.left)/r.width*94-47,(e.clientY-r.top)/r.height*80-40)};
let touchId=null;const joystick=$('touchMove');function joy(e){const r=joystick.getBoundingClientRect();let x=clamp((e.clientX-r.left-r.width/2)/36,-1,1),z=clamp((e.clientY-r.top-r.height/2)/36,-1,1);touchVector={x,z};joystick.firstChild.style.transform=`translate(${x*29}px,${z*29}px)`;}
joystick.addEventListener('pointerdown',e=>{touchId=e.pointerId;joystick.setPointerCapture(e.pointerId);joy(e)});joystick.addEventListener('pointermove',e=>{if(e.pointerId===touchId)joy(e)});for(const event of ['pointerup','pointercancel'])joystick.addEventListener(event,()=>{touchId=null;touchVector={x:0,z:0};joystick.firstChild.style.transform='none'});$('touchAttack').addEventListener('pointerdown',e=>{e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);mouseDown=true;});$('touchAttack').addEventListener('pointerup',()=>mouseDown=false);$('touchAttack').addEventListener('pointercancel',()=>mouseDown=false);
startScreen();requestAnimationFrame(frame);
if(document.modelContext?.registerTool){const life=new AbortController();const tools=[{name:'read_match_state',title:'查看裂境戰局',description:'Read the current match state, hero, score, evolution and boss status.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({state,seconds:Math.floor(time),hero:player?HEROES[player.hero].name:null,health:player?Math.ceil(player.hp):null,score:scores,evolutions:chosen.map(u=>u.name),boss:boss?{team:boss.team,health:boss.hp}:null})},{name:'start_match',title:'開始裂境戰鬥',description:'Start a new match from the hero selection screen. Hero 0 swordsman, 1 archer, 2 mage, 3 fighter.',inputSchema:{type:'object',properties:{hero:{type:'integer',minimum:0,maximum:3}},required:['hero'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>startGame(input?.hero)}];for(const tool of tools)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{})}catch{}window.addEventListener('pagehide',()=>life.abort(),{once:true});}
